import{_ as n,C as i,o as r,c as a,j as t,a as s,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const m=JSON.parse('{"title":"Piwi Picker and your editor","description":"How Piwi Picker reaches the VS Code and JetBrains windows on your machine for Send to editor and the Runs window: the pairing, the proof asked before any token goes, the windows found as they open, and what it says when one does not answer.","frontmatter":{"title":"Piwi Picker and your editor","description":"How Piwi Picker reaches the VS Code and JetBrains windows on your machine for Send to editor and the Runs window: the pairing, the proof asked before any token goes, the windows found as they open, and what it says when one does not answer.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-pairing.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-pairing.html"}],["meta",{"property":"og:title","content":"Piwi Picker and your editor | Piwi for Playwright"}],["meta",{"property":"og:description","content":"How Piwi Picker reaches the VS Code and JetBrains windows on your machine for Send to editor and the Runs window: the pairing, the proof asked before any token goes, the windows found as they open, and what it says when one does not answer."}]]},"headers":[],"relativePath":"features/editor-pairing.md","filePath":"features/editor-pairing.md","lastUpdated":1793959624000}'),w={name:"features/editor-pairing.md"};function p(l,e,c,u,g,f){const o=i("Needs");return r(),a("div",null,[e[0]||(e[0]=t("h1",{id:"piwi-picker-and-your-editor",tabindex:"-1"},[s("Piwi Picker and your editor "),t("a",{class:"header-anchor",href:"#piwi-picker-and-your-editor","aria-label":'Permalink to "Piwi Picker and your editor"'},"​")],-1)),d(o,{extension:""}),e[1]||(e[1]=h('<p><a href="./editor-recording.html#send-from-piwi-picker">Send to editor</a> and the <a href="./runs-window.html">Runs window</a> reach your editor through one pairing: the address <strong>Piwi: Pair with Piwi Picker</strong> copies, pasted under <strong>Send to editor</strong> in Piwi Picker&#39;s settings. The desktop app has a pairing of its own, which the Runs window follows beside it.</p><h2 id="what-the-pairing-reaches" tabindex="-1">What the pairing reaches <a class="header-anchor" href="#what-the-pairing-reaches" aria-label="Permalink to &quot;What the pairing reaches&quot;">​</a></h2><p>The editor listens on the loopback interface only, answers only a request addressed to <code>127.0.0.1</code> or <code>localhost</code> at its port, and accepts one only with the token. Before Piwi Picker sends the token, the editor proves it holds it, so another program that took the port is sent nothing; the settings ask for that proof as they open and after <strong>Pair</strong>. With several VS Code windows open, the one holding the paired port receives; when it closes, another open window takes the port within seconds, unless every other one already listens on a port of its own for a run it started meanwhile.</p><p>Piwi Picker&#39;s background worker reaches the editor&#39;s services on <code>127.0.0.1</code> only once the paired port proves it holds the pairing&#39;s token (<a href="./editor-run-control.html#how-it-works">how the pieces connect</a>), as the desktop app proves it holds its own. The Runs window talks to that worker alone, and makes no network call of its own. An older editor extension gives the image and the controls alone.</p><h2 id="windows-that-open-and-close" tabindex="-1">Windows that open and close <a class="header-anchor" href="#windows-that-open-and-close" aria-label="Permalink to &quot;Windows that open and close&quot;">​</a></h2><p>An editor window you open later shows in the Runs window within seconds: each window&#39;s service names the others, without their tokens, and the worker asks the paired editor for them. While the Runs window is open, it also asks every minute. A run whose window stops answering stays listed, grayed and as last heard, until that window answers again, ten minutes at most, and a stop&#39;s <strong>Watch live</strong> starts again then.</p><h2 id="when-the-editor-does-not-answer" tabindex="-1">When the editor does not answer <a class="header-anchor" href="#when-the-editor-does-not-answer" aria-label="Permalink to &quot;When the editor does not answer&quot;">​</a></h2><p>A line under the Runs window&#39;s title says how each paired tool stands, a broken pairing included, with <strong>Look again</strong> or <strong>Open the settings</strong> where its sentence needs them. When the paired port answers without proving it holds the token, the worker asks a few times more, then once a minute while the Runs window is open: pair again from the settings if the editor moved to another port. One that answers with no proof and no such page is not your editor&#39;s Piwi extension. While no window of a paired tool answers, the popup&#39;s <strong>Runs</strong> tile stays, muted, and the Runs window says why.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./runs-window.html">Runs window</a>: the runs it follows, and their controls.</li><li><a href="./editor-recording.html#send-from-piwi-picker">Record tests from the editor</a>: pairing, and what Send to editor inserts.</li><li><a href="/guide/remote-development.html">Remote development</a>: the pairing address of a remote window.</li><li><a href="./extension.html">Browser extension</a>: Piwi Picker&#39;s other tools, and its permissions.</li></ul>',10))])}const P=n(w,[["render",p]]);export{m as __pageData,P as default};
